package com.admira.admirito;
import android.app.*;
import android.content.*;
import android.media.*;
import android.os.*;
import org.json.*;
import java.io.*;
import java.nio.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;

/** Explicit microphone foreground session, closed WAV chunks and durable idempotent queue. */
public final class ListeningService extends Service {
 static volatile boolean active;
 private volatile boolean capture; private AudioRecord audio; private PowerManager.WakeLock lock;
 private final ExecutorService executor=Executors.newSingleThreadExecutor();
 private JSONObject note;private File folder;private Api api;
 @Override public IBinder onBind(Intent i){return null;}
 @Override public void onCreate(){super.onCreate();NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("listening","Escuchas de Admirito",NotificationManager.IMPORTANCE_LOW));}
 private Notification notification(String text){PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);PendingIntent stop=PendingIntent.getService(this,1,new Intent(this,ListeningService.class).setAction("finish"),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);return new Notification.Builder(this,"listening").setSmallIcon(android.R.drawable.ic_btn_speak_now).setContentTitle("Admirito").setContentText(text).setContentIntent(open).setOngoing(true).addAction(new Notification.Action.Builder(null,"Terminar y resumir",stop).build()).build();}
 private void notice(String text){getSystemService(NotificationManager.class).notify(17,notification(text));}
 @Override public int onStartCommand(Intent intent,int flags,int startId){if(intent==null)return START_NOT_STICKY;String action=intent.getAction();if("finish".equals(action)){capture=false;notice("Cerrando audio y preparando resumen…");if(audio!=null)try{audio.stop();}catch(Exception ignored){}return START_NOT_STICKY;}if(active)return START_NOT_STICKY;
  try{api=new Api(this);if(api.account().isEmpty()){stopSelf();return START_NOT_STICKY;}startForeground(17,notification("Preparando escucha…"));active=true;lock=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"Admirito:listening");lock.acquire(11*60*60*1000L);
   if("start".equals(action)){String account=intent.getStringExtra("account");if(!api.account().equals(account))throw new IOException("account_changed");String id=UUID.randomUUID().toString();folder=new File(getNoBackupFilesDir(),"listening/"+id);folder.mkdirs();note=Api.object("id",id,"account",account,"conversation",intent.getStringExtra("conversation"),"kind",intent.getStringExtra("kind"),"started",System.currentTimeMillis(),"finished",false,"complete",false,"rest",intent.getBooleanExtra("rest",false));save();File photo=new File(getNoBackupFilesDir(),"projection-"+account+".jpg");if(note.getString("kind").equals("movie")&&photo.exists()){Files.copy(photo.toPath(),new File(folder,"photo.jpg").toPath(),StandardCopyOption.REPLACE_EXISTING);photo.delete();}capture=true;executor.execute(()->runCapture());}
   else executor.execute(()->recoverAll());
  }catch(Exception e){active=false;stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}return START_NOT_STICKY;
 }
 private void save()throws Exception{writeAtomic(new File(folder,"note.json"),note.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 static void writeAtomic(File file,byte[] bytes)throws Exception{File tmp=new File(file.getPath()+".tmp");try(FileOutputStream out=new FileOutputStream(tmp)){out.write(bytes);out.getFD().sync();}Files.move(tmp.toPath(),file.toPath(),StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}
 private void runCapture(){try{if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=android.content.pm.PackageManager.PERMISSION_GRANTED)throw new SecurityException("microphone_permission_required");int min=AudioRecord.getMinBufferSize(16000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT);audio=new AudioRecord(MediaRecorder.AudioSource.MIC,16000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT,Math.max(8192,min*2));if(audio.getState()!=AudioRecord.STATE_INITIALIZED)throw new IOException("microphone_unavailable");audio.startRecording();notice("Escuchando · puedes bloquear el teléfono");byte[] buffer=new byte[3200];ByteArrayOutputStream pcm=new ByteArrayOutputStream();long total=0,silent=0;int seq=0;
   while(capture&&seq<1440){int n=audio.read(buffer,0,buffer.length);if(n<=0){if(!capture)break;throw new IOException("microphone_interrupted");}pcm.write(buffer,0,n);total+=n;long energy=0;for(int i=0;i+1<n;i+=2){short sample=(short)((buffer[i]&255)|(buffer[i+1]<<8));energy+=Math.abs((int)sample);}double amplitude=energy/(double)Math.max(1,n/2);silent=amplitude<120?silent+n:0;
    if(pcm.size()>=800000){writeChunk(seq++,pcm.toByteArray(),(total-pcm.size())/32000.0);pcm.reset();}
    if(silent>=32000L*300){capture=false;note.put("stop_reason","five_minutes_low_sound");}
   }
   if(pcm.size()>3200)writeChunk(seq,pcm.toByteArray(),(total-pcm.size())/32000.0);note.put("finished",true);note.put("ended",System.currentTimeMillis());save();restEstimate();
  }catch(Exception e){try{note.put("finished",true);note.put("interrupted",true);save();}catch(Exception ignored){}}
  finally{capture=false;if(audio!=null){try{audio.stop();}catch(Exception ignored){}audio.release();audio=null;}}
  try{upload(folder,note);}catch(Exception e){notice("Pendiente de envío · abre Admirito para recuperar");}finally{endService();}
 }
 private void writeChunk(int seq,byte[] pcm,double start)throws Exception{String name=String.format(Locale.ROOT,"%04d",seq);ByteBuffer wav=ByteBuffer.allocate(44+pcm.length).order(ByteOrder.LITTLE_ENDIAN);wav.put("RIFF".getBytes()).putInt(36+pcm.length).put("WAVEfmt ".getBytes()).putInt(16).putShort((short)1).putShort((short)1).putInt(16000).putInt(32000).putShort((short)2).putShort((short)16).put("data".getBytes()).putInt(pcm.length).put(pcm);writeAtomic(new File(folder,name+".wav"),wav.array());long energy=0;for(int i=0;i+1<pcm.length;i+=2)energy+=Math.abs((int)(short)((pcm[i]&255)|(pcm[i+1]<<8)));writeAtomic(new File(folder,name+".json"),Api.object("seq",seq,"start_seconds",start,"duration_seconds",pcm.length/32000.0,"silent",energy/(double)Math.max(1,pcm.length/2)<120).toString().getBytes());}
 private void restEstimate(){try{int hour=Calendar.getInstance().get(Calendar.HOUR_OF_DAY);if(note.optBoolean("rest")&&note.optString("kind").equals("movie")&&(hour>=20||hour<4))getSharedPreferences("rest-"+note.getString("account"),0).edit().putLong("bed",System.currentTimeMillis()).apply();}catch(Exception ignored){}}
 private void upload(File dir,JSONObject n)throws Exception{if(!api.account().equals(n.getString("account")))throw new IOException("account_changed");if(n.optBoolean("complete"))return;File[] files=dir.listFiles((d,name)->name.matches("[0-9]{4}\\.json"));if(files==null||files.length==0)return;Arrays.sort(files);String id=n.getString("id");api.json("agents/listening",Api.object("id",id,"conversation_id",n.getString("conversation"),"kind",n.getString("kind"),"title","Escucha Android"));int count=0;
  for(File file:files){JSONObject chunk=new JSONObject(Api.text(file.toPath()));if(chunk.getInt("seq")!=count)throw new IOException("missing_chunk");String text=chunk.optString("text",null);if(text==null){if(chunk.optBoolean("silent"))text="";else{File wav=new File(dir,file.getName().replace(".json",".wav"));try{text=api.request("agents/transcribe",Files.readAllBytes(wav.toPath()),"audio/wav").optString("text");}catch(IOException e){if("no_speech".equals(e.getMessage()))text="";else throw e;}}chunk.put("text",text);writeAtomic(file,chunk.toString().getBytes());}if(!chunk.optBoolean("sent")){api.json("agents/listening/"+id+"/chunks",Api.object("seq",count,"start_seconds",chunk.getDouble("start_seconds"),"duration_seconds",chunk.getDouble("duration_seconds"),"text",text));chunk.put("sent",true);writeAtomic(file,chunk.toString().getBytes());}count++;notice("Guardados "+count+" de "+files.length+" fragmentos");}
  for(int attempt=0;attempt<40;attempt++){JSONObject result=api.json("agents/listening/"+id+"/summary",Api.object("expected_chunks",count));if(result.optString("status").equals("complete")){n.put("summary",result.optString("summary"));n.put("complete",true);n.put("finished",true);writeAtomic(new File(dir,"note.json"),n.toString().getBytes());getSharedPreferences("listening",0).edit().putString(api.account(),id).commit();for(File f:Objects.requireNonNull(dir.listFiles((d,name)->name.endsWith(".wav"))))f.delete();return;}Thread.sleep(3000);}throw new IOException("summary_pending");
 }
 private void recoverAll(){try{File parent=new File(getNoBackupFilesDir(),"listening");File[] dirs=parent.listFiles(File::isDirectory);if(dirs!=null)for(File dir:dirs){File f=new File(dir,"note.json");if(!f.exists())continue;JSONObject n=new JSONObject(Api.text(f.toPath()));if(n.optString("account").equals(api.account())&&!n.optBoolean("complete")){if(!n.optBoolean("finished")){n.put("finished",true);n.put("interrupted",true);writeAtomic(f,n.toString().getBytes());}upload(dir,n);}}}catch(Exception e){notice("Resumen pendiente · revisa la conexión y recupera desde la app");}finally{endService();}}
 private void endService(){active=false;if(lock!=null&&lock.isHeld())lock.release();stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}
 static void recover(Context context){if(active||context.checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=android.content.pm.PackageManager.PERMISSION_GRANTED)return;try{Api api=new Api(context);if(api.account().isEmpty())return;File parent=new File(context.getNoBackupFilesDir(),"listening");File[] dirs=parent.listFiles(File::isDirectory);if(dirs!=null)for(File dir:dirs){File note=new File(dir,"note.json");if(!note.exists())continue;JSONObject n=new JSONObject(Api.text(note.toPath()));if(n.optString("account").equals(api.account())&&!n.optBoolean("complete")){context.startForegroundService(new Intent(context,ListeningService.class).setAction("recover"));return;}}}catch(Exception ignored){}}
 static JSONObject latest(Context context,String account)throws Exception{String id=context.getSharedPreferences("listening",0).getString(account,"");if(id.isEmpty())throw new IOException("summary_required");return new JSONObject(Api.text(new File(context.getNoBackupFilesDir(),"listening/"+id+"/note.json").toPath()));}
 @Override public void onDestroy(){capture=false;if(audio!=null)try{audio.stop();}catch(Exception ignored){}if(lock!=null&&lock.isHeld())lock.release();active=false;super.onDestroy();}
}
